def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    def merge_two(order1, order2):
        if not order1 or not order2:
            return order1 or order2
        if order1[0] == order2[0]:
            return [order1[0]] + merge_two(order1[1:], order2[1:])
        if order1[0] in order2:
            index = order2.index(order1[0])
            return order2[:index] + [order1[0]] + merge_two(order1[1:], order2[index+1:])
        if order2[0] in order1:
            index = order1.index(order2[0])
            return order1[:index] + [order2[0]] + merge_two(order1[index+1:], order2[1:])
        return [order1[0]] + merge_two(order1[1:], order2)

    from functools import reduce
    return reduce(merge_two, orderings)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    for cls in classes:
        if not any(issubclass(c, cls) for c in minimal):
            minimal.append(cls)
        else:
            minimal = [c for c in minimal if not issubclass(cls, c)]
    return minimal

