def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if self._valid_coordinate(coord):
        self._data[coord] += weight

def _valid_coordinate(self, coord):
    return all(low <= c < high for c, (low, high) in zip(coord, zip(self._edges[:-1], self._edges[1:])))

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if all(self.edges[i][0] <= coord[i] < self.edges[i][-1] for i in range(self.ndim)):
        indices = tuple(
            np.searchsorted(self.edges[i], coord[i], side='right') - 1
            for i in range(self.ndim)
        )
        self.counts[indices] += weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from django.core.exceptions import ValidationError

    key_regex = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_]*$')
    value_regex = re.compile(r'^[a-zA-Z0-9._-]+$')
    errors = []

    for key, value in labels.items():
        # Check if key is a string
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
            continue
        # Check if key matches regex
        if not key_regex.match(key):
            errors.append({key: f"Label key '{key}' does not match the regex '{key_regex.pattern}'"})

        # Check if value is a string or list of strings
        if isinstance(value, str):
            if not value_regex.match(value):
                errors.append({value: f"Label value '{value}' does not match the regex '{value_regex.pattern}'"})
        elif isinstance(value, list):
            for item in value:
                if not isinstance(item, str):
                    errors.append({str(item): 'expected string or bytes-like object'})
                elif not value_regex.match(item):
                    errors.append({item: f"Label value '{item}' does not match the regex '{value_regex.pattern}'"})
        else:
            errors.append({str(value): 'expected string or bytes-like object'})

    if errors:
        raise ValidationError(messages=errors)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present
    """
    for schema_item, resp_item in zip(observer_schema, response):
        if isinstance(schema_item, dict):
            # Assuming that if schema_item is a dict, response item can be a dict or a list
            # Create entry in last_applied_manifest if not present
            manifest_index = next(
                (i for i, item in enumerate(last_applied_manifest) if item['name'] == schema_item['name']),
                None
            )
            if manifest_index is None:
                manifest_index = len(last_applied_manifest)
                last_applied_manifest.append({"name": schema_item['name'], "value": {}})
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[manifest_index]['value'], schema_item['value'], resp_item
            )
        elif isinstance(schema_item, list):
            # Assuming that if schema_item is a list, response item is also a list
            # Create entry in last_applied_manifest if not present
            if len(last_applied_manifest) <= len(schema_item):
                last_applied_manifest.append([])
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[len(last_applied_manifest) - 1], schema_item, resp_item
            )
        else:
            # schema_item is a primitive type, set directly if not present
            if len(last_applied_manifest) <= len(schema_item):
                last_applied_manifest.append(resp_item)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for obs, resp in zip(observer_schema, response):
        if isinstance(obs, dict) and isinstance(resp, dict):
            for key in obs:
                if key not in last_applied_manifest:
                    last_applied_manifest[key] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], obs[key], resp.get(key, {})
                )
        elif isinstance(obs, list) and isinstance(resp, list):
            for i in range(max(len(obs), len(resp))):
                if i >= len(last_applied_manifest):
                    last_applied_manifest.append([])
                if i < len(obs) and i < len(resp):
                    update_last_applied_manifest_list_from_resp(
                        last_applied_manifest[i], obs[i], resp[i]
                    )
                elif i < len(obs):
                    last_applied_manifest[i] = obs[i]
                elif i < len(resp):
                    last_applied_manifest[i] = resp[i]

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for field, schema in observer_schema.items():
        if field in response:
            if isinstance(schema, dict):
                if field not in last_applied_manifest:
                    last_applied_manifest[field] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field], schema, response[field]
                )
            elif isinstance(schema, list):
                if field not in last_applied_manifest:
                    last_applied_manifest[field] = []
                # Assuming schema is a list of dicts for recursion
                if schema and isinstance(schema[0], dict):
                    for idx, item in enumerate(response[field]):
                        if idx >= len(last_applied_manifest[field]):
                            last_applied_manifest[field].append({})
                        update_last_applied_manifest_dict_from_resp(
                            last_applied_manifest[field][idx], schema[0], item
                        )
            else:
                if field not in last_applied_manifest:
