def format(
		self,
		sql: AnyStr,
		params: Union[Dict[Union[str, int], Any], Sequence[Any]],
	) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		"""
		Convert the SQL query to use the out-style parameters instead of
		the in-style parameters.

		*sql* (:class:`str` or :class:`bytes`) is the SQL query.

		*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
		contains the set of in-style parameters. It maps each parameter
		(:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
		is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
		If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
		*params* must be a :class:`~collections.abc.Sequence`.

		Returns a :class:`tuple` containing:

		-	The formatted SQL query (:class:`str` or :class:`bytes`).

		-	The set of converted out-style parameters (:class:`dict` or
			:class:`list`).
		"""
		from_style = self.SQLParams.in_style
		to_style = self.SQLParams.out_style

		if from_style == to_style:
			return sql, params

		if from_style == 'named':
			if to_style == 'qmark':
				new_sql = sql
				out_params = []
				for k, v in params.items():
					new_sql = new_sql.replace(':' + k, '?')
					out_params.append(v)
				return new_sql, out_params
			elif to_style == 'numeric':
				new_sql = sql
				out_params = []
				for k, v in params.items():
					new_sql = new_sql.replace(':' + k, '?')
					out_params.append(v)
				return new_sql, out_params
			elif to_style == 'named':
				return sql, params
			elif to_style == 'format':
				new_sql = sql
				for k, v in params.items():
					new_sql = new_sql.replace(':' + k, '%(' + k + ')s')
				return new_sql, params
			elif to_style == 'pyformat':
				return sql, params
		elif from_style == 'qmark':
			if to_style == 'named':
				new_sql = sql
				out_params = {}
				for i, v in enumerate(params):
					param_name = 'param' + str(i)
					new_sql = new_sql.replace('?', ':' + param_name)
					out_params[param_name] = v
				return new_sql, out_params
			elif to_style == 'numeric':
				new_sql = sql
				out_params = list(params)
				return new_sql, out_params
			elif to_style == 'qmark':
				return sql, params
			elif to_style == 'format':
				new_sql = sql
				out_params = list(params)
				return new_sql, out_params
			elif to_style == 'pyformat':
				new_sql = sql
				out_params = {}
				for i, v in enumerate(params):
					param_name = 'param' + str(i)
					new_sql = new_sql.replace('?', '%(' + param_name + ')s')
					out_params[param_name] = v
				return new_sql, out_params
		elif from_style == 'numeric':
			if to_style == 'named':
				new_sql = sql
				out_params = {}
				for i, v in enumerate(params):
					param_name = 'param' + str(i)
					new_sql = new_sql.replace(':' + str(i + 1), ':' + param_name)
					out_params[param_name] = v
				return new_sql, out_params
			elif to_style == 'qmark':
				new_sql = sql
				out_params = list(params)
				for i in range(len(out_params)):
					new_sql = new_sql.replace(':' + str(i + 1), '?')
				return new_sql, out_params
			elif to_style == 'numeric':
				return sql, params
			elif to_style == 'format':
				new_sql = sql
				out_params = list(params)
				return new_sql, out_params
			elif to_style == 'pyformat':
				new_sql = sql
				out_params = {}
				for i, v in enumerate(params):
					param_name = 'param' + str(i)
					new_sql = new_sql.replace(':' + str(i + 1), '%(' + param_name + ')s')
					out_params[param_name] = v
				return new_sql, out_params
		elif from_style == 'format':
			if to_style == 'named':
				new_sql = sql
				out_params = {}
				for i, v in enumerate(params):
					param_name = 'param' + str(i)
					new_sql = new_sql.replace('%s', ':' + param_name, 1)
					out_params[param_name] = v
				return new_sql, out_params
			elif to_style == 'qmark':
				new_sql = sql.replace('%s', '?')
				out_params = list(params)
				return new_sql, out_params
			elif to_style == 'numeric':
				new_sql = sql
				out_params = list(params)
				for i in range(len(out_params)):
					new_sql = new_sql.replace('%s', ':' + str(i + 1), 1)
				return new_sql, out_params
			elif to_style == 'format':
				return sql, params
			elif to_style == 'pyformat':
				new_sql = sql
				out_params = {}
				for i, v in enumerate(params):
					param_name = 'param' + str(i)
					new_sql = new_sql.replace('%s', '%(' + param_name + ')s', 1)
					out_params[param_name] = v
				return new_sql, out_params
		elif from_style == 'pyformat':
			if to_style == 'named':
				return sql, params
			elif to_style == 'qmark':
				new_sql = sql
				out_params = []
				for k, v in params.items():
					new_sql = new_sql.replace('%(' + k + ')s', '?')
					out_params.append(v)
				return new_sql, out_params
			elif to_style == 'numeric':
				new_sql = sql
				out_params = []
				for k, v in params.items():
					new_sql = new_sql.replace('%(' + k + ')s', '?')
					out_params.append(v)
				return new_sql, out_params
			elif to_style == 'format':
				new_sql = sql
				out_params = list(params.values())
				new_sql = new_sql.replace('%(', '%s')
				new_sql = new_sql.replace(')', '')
				return new_sql, out_params
			elif to_style == 'pyformat':
				return sql, params

		raise ValueError("Unsupported parameter style conversion")

