def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("Prior must be an instance of InventoryValidator")

    if len(self.inventory) != len(prior.inventory):
        raise ValueError("Inventory and prior inventory must have the same number of items")

    for item, prior_item in zip(self.inventory, prior.inventory):
        if item['name'] != prior_item['name']:
            raise ValueError(f"Item names do not match: {item['name']} != {prior_item['name']}")
        if item['quantity'] < prior_item['quantity']:
            raise ValueError(f"Item {item['name']} quantity in inventory must not be less than in prior inventory: "
                             f"{item['quantity']} < {prior_item['quantity']}")

