def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    parts = [indent_str + "Object Type: " + str(type(self).__name__)]
    if debug:
        parts.append(indent_str + "ID: " + str(id(self)))
    for attr, value in self.__dict__.items():
        if isinstance(value, list):
            parts.append(indent_str + attr + ": [")
            for item in value:
                if hasattr(item, 'pretty'):
                    parts.append(item.pretty(indent + 2, debug))
                else:
                    parts.append(' ' * (indent + 2) + str(item))
            parts.append(indent_str + "]")
        elif hasattr(value, 'pretty'):
            parts.append(indent_str + attr + ":")
            parts.append(value.pretty(indent + 2, debug))
        else:
            parts.append(indent_str + attr + ": " + str(value))
    return "\n".join(parts)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    output = f"{indent_str}Class: {self.__class__.__name__}\n"
    for attr, value in self.__dict__.items():
        if isinstance(value, list):
            output += f"{indent_str}  {attr}: [\n"
            for item in value:
                if hasattr(item, 'pretty'):
                    output += item.pretty(indent=indent + 4, debug=debug)
                else:
                    output += f"{indent_str}    {item}\n"
            output += f"{indent_str}  ]\n"
        elif hasattr(value, 'pretty'):
            output += f"{indent_str}  {attr}:\n"
            output += value.pretty(indent=indent + 2, debug=debug)
        else:
            output += f"{indent_str}  {attr}: {value}\n"
    if debug:
        output += f"{indent_str}  id: {id(self)}\n"
    return output

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from copy import deepcopy

    def is_complement(expr1, expr2):
        return expr1 == f"~{expr2}" or expr2 == f"~{expr1}"

    new_args = deepcopy(args)
    i = 0
    while i < len(new_args) - 1:
        a1 = new_args[i]
        op = new_args[i + 1]
        a2 = new_args[i + 2] if i + 2 < len(new_args) else None
        if a2 and op == '&':
            if a2.startswith('(') and a2.endswith(')'):
                inner_expr = a2[1:-1]
                if '|' in inner_expr:
                    b1, b2 = inner_expr.split('|')
                    if a1 == b1 or is_complement(a1, b1):
                        new_args = new_args[:i] + [a1] + new_args[i + 3:]
                        continue
                    elif a1 == b2 or is_complement(a1, b2):
                        new_args = new_args[:i] + [a1] + new_args[i + 3:]
                        continue
        elif a2 and op == '|':
            if a2.startswith('(') and a2.endswith(')'):
                inner_expr = a2[1:-1]
                if '&' in inner_expr:
                    b1, b2 = inner_expr.split('&')
                    if a1 == b1 or is_complement(a1, b1):
                        new_args = new_args[:i] + [a1] + new_args[i + 3:]
                        continue
                    elif a1 == b2 or is_complement(a1, b2):
                        new_args = new_args[:i] + [a1] + new_args[i + 3:]
                        continue
        i += 1
    return new_args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if len(args) != 3:
        return args

    a, op1, expr = args
    if isinstance(expr, list) and len(expr) == 3:
        b, op2, c = expr
        if op1 == '&' and op2 == '|':
            if a == b:
                return a
            elif a == '~' + b:
                return [a, '&', c]
        elif op1 == '|' and op2 == '&':
            if a == b:
                return a
            elif a == '~' + b:
                return [a, '|', c]
    return args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from collections.abc import Iterable

    def is_iterable_and_not_string(obj):
        return isinstance(obj, Iterable) and not isinstance(obj, str)

    new_args = []
    i = 0
    while i < len(args):
        expr = args[i]
        if is_iterable_and_not_string(expr) and len(expr) == 3:
            op, left, right = expr
            if op == '&':
                if right == ('|', left, object()):
                    new_args.append(left)
                elif right == ('&', ('~', left, ()), object()):
                    new_args.append(('&', left, right[2]))
                else:
                    new_args.append(expr)
            elif op == '|':
                if right == ('&', left, object()):
                    new_args.append(left)
                elif right == ('|', ('~', left, ()), object()):
                    new_args.append(('|', left, right[2]))
                else:
                    new_args.append(expr)
            else:
                new_args.append(expr)
        else:
            new_args.append(expr)
        i += 1
    return new_args

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return [n.encode() for n in namefunc(*args, **kwargs)]
    return inner_func

