def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if not isinstance(commands, list):
        commands = [commands]

    full_command = commands + args
    process_env = os.environ.copy() if env is None else env

    try:
        if hide_stderr:
            with open(os.devnull, 'w') as devnull:
                output = subprocess.check_output(full_command, cwd=cwd, env=process_env, stderr=devnull)
        else:
            output = subprocess.check_output(full_command, cwd=cwd, env=process_env)

        if verbose:
            print(f"Command executed successfully: {' '.join(full_command)}")
            print(f"Output: {output.decode('utf-8')}")

        return output.decode('utf-8')

    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed: {' '.join(full_command)}")
            print(f"Error: {e.output.decode('utf-8')}")

        raise RuntimeError(f"Command {' '.join(full_command)} failed with return code {e.returncode}") from e

