def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = None
    content_digests = {}

    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory.json')
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory file not found for version {version_dir}")

        with open(inventory_path, 'r') as f:
            inventory = json.load(f)

        if root_inventory is None:
            root_inventory = inventory

        for item, digest in inventory.items():
            if item in root_inventory and root_inventory[item] != digest:
                content_digests[item] = digest

    return content_digests

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = self.load_inventory(version_dirs[0])
    all_content_digests = set(root_inventory.get('content_digests', []))
    for version in version_dirs[1:]:
        inventory_path = os.path.join(version, 'inventory.json')
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory file not found for version {version}")
        inventory = self.load_inventory(inventory_path)
        content_digests = set(inventory.get('content_digests', []))
        if not content_digests.issubset(all_content_digests):
            diff = content_digests - all_content_digests
            self.record_content_differences(version, diff)
        all_content_digests.update(content_digests)

def load_inventory(self, path):
    with open(path, 'r') as f:
        return json.load(f)

def record_content_differences(self, version, differences):
    if not hasattr(self, 'content_differences'):
        self.content_differences = {}
    self.content_differences[version] = differences

def validate_version_inventories(self, version_dirs):
