def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    if size.endswith('K'):
        return int(size[:-1]) * 1000
    elif size.endswith('M'):
        return int(size[:-1]) * 1000**2
    elif size.endswith('G'):
        return int(size[:-1]) * 1000**3
    elif size.endswith('T'):
        return int(size[:-1]) * 1000**4
    elif size.endswith('P'):
        return int(size[:-1]) * 1000**5
    elif size.endswith('E'):
        return int(size[:-1]) * 1000**6
    else:
        return int(size)

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    suffix = size[-1].upper()
    prefix = size[:-1]

    if prefix.isdigit():
        size_in_bytes = int(prefix)
    else:
        raise ValueError("Size value must start with a number")

    if suffix == 'K':
        size_in_bytes *= 1000
    elif suffix == 'M':
        size_in_bytes *= 1000**2
    elif suffix == 'G':
        size_in_bytes *= 1000**3
    elif suffix == 'T':
        size_in_bytes *= 1000**4
    elif suffix == 'P':
        size_in_bytes *= 1000**5
    elif suffix == 'E':
        size_in_bytes *= 1000**6
    elif suffix == 'Z':
        size_in_bytes *= 1000**7
    elif suffix == 'Y':
        size_in_bytes *= 1000**8
    elif suffix not in '0123456789':
        raise ValueError("Invalid suffix. Only K, M, G, T, P, E, Z, Y are supported.")

    return size_in_bytes

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

