    """Return all subclasses of a class, recursively"""
    result = set()

    def _subclasses(c):
        for sub in c.__subclasses__():
            if sub not in result:
                result.add(sub)
                _subclasses(sub)

    _subclasses(cls)
    return result

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for c in sc:
            if c not in seen:
                queue.add(c)

    seen.remove(cls)
    return seen

