def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency == "always":
        return None

    import re
    match = re.match(r'^(\d+)\s*(\w+)$', frequency)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    number, unit = match.groups()
    number = int(number)

    if unit in ['week', 'weeks']:
        return datetime.timedelta(weeks=number)
    elif unit in ['day', 'days']:
        return datetime.timedelta(days=number)
    elif unit in ['hour', 'hours']:
        return datetime.timedelta(hours=number)
    elif unit in ['minute', 'minutes']:
        return datetime.timedelta(minutes=number)
    elif unit in ['second', 'seconds']:
        return datetime.timedelta(seconds=number)

    raise ValueError(f"Unknown time unit: {unit}")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency == "always":
        return None

    # Define a mapping from string units to timedelta keyword arguments
    units = {
        'seconds': 'seconds',
        'minutes': 'minutes',
        'hours': 'hours',
        'days': 'days',
        'weeks': 'weeks'
    }

    # Split the frequency string into number and unit
    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    try:
        number = int(parts[0])
    except ValueError:
        raise ValueError(f"Cannot parse frequency number: {parts[0]}")

    unit = parts[1].rstrip('s')  # Handle plural and singular units
    if unit not in units:
        raise ValueError(f"Unknown time unit: {unit}")

    # Create a timedelta object with the appropriate keyword argument
    kwargs = {units[unit]: number}
    return datetime.timedelta(**kwargs)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency == "always":
        return None

    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError(f"Invalid frequency format: {frequency}")

    try:
        number = int(parts[0])
    except ValueError:
        raise ValueError(f"Invalid number in frequency: {frequency}")

    unit = parts[1].rstrip('s')  # remove plural 's' if present
    if unit == 'week':
        return datetime.timedelta(weeks=number)
    elif unit == 'day':
        return datetime.timedelta(days=number)
    elif unit == 'hour':
        return datetime.timedelta(hours=number)
    elif unit == 'minute':
        return datetime.timedelta(minutes=number)
    elif unit == 'second':
        return datetime.timedelta(seconds=number)
    else:
        raise ValueError(f"Unknown time unit in frequency: {frequency}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        return socket.gethostbyname(host) == socket.gethostbyname('localhost')
    except socket.gaierror:
        return False

