def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess

    for command in commands:
        full_command = [command] + args
        try:
            if verbose:
                print("Running:", ' '.join(full_command))
            with subprocess.Popen(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT) as process:
                stdout, stderr = process.communicate()
                if verbose:
                    print("Output:\n", stdout.decode())
                if process.returncode != 0:
                    raise subprocess.CalledProcessError(process.returncode, full_command, output=stdout, stderr=stderr)
        except subprocess.CalledProcessError as e:
            if verbose:
                print("Error:", e.stderr.decode() if hide_stderr else e.output.decode())
            raise

