def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import logging.config
    import os
    import json

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        if not os.path.exists(filename):
            log_record = logging.makeLogRecord({
                'name': 'config_loader',
                'levelname': logging.ERROR,
                'msg': f'Configuration file {filename} does not exist.'
            })
            log_records.append(log_record)
            continue

        try:
            with open(filename, 'r') as file:
                config = json.load(file)
            config_dict[filename] = config
        except json.JSONDecodeError as e:
            log_record = logging.makeLogRecord({
                'name': 'config_loader',
                'levelname': logging.ERROR,
                'msg': f'Error decoding JSON from {filename}: {str(e)}'
            })
            log_records.append(log_record)

    if overrides:
        for key, value in overrides.items():
            for config in config_dict.values():
                config[key] = value

    if resolve_env:
        import re
        env_var_pattern = re.compile(r'\$\{(\w+)\}')
        for config in config_dict.values():
            for key, value in config.items():
                if isinstance(value, str):
                    matches = env_var_pattern.findall(value)
                    for match in matches:
                        env_value = os.getenv(match)
                        if env_value:
                            value = value.replace(f'${{{match}}}', env_value)
                    config[key] = value

    return config_dict, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import os
    import toml
    from logging import LogRecord

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        if not os.path.exists(filename):
            log_records.append(LogRecord('config_loader', logging.ERROR, filename, 0, f"Configuration file {filename} does not exist.", (), None))
            continue

        try:
            with open(filename, 'r') as file:
                config = toml.load(file)
                config_dict[filename] = config
        except Exception as e:
            log_records.append(LogRecord('config_loader', logging.ERROR, filename, 0, f"Failed to parse configuration file {filename}: {str(e)}", (), None))

    if overrides:
        for key, value in overrides.items():
            for config in config_dict.values():
                config[key] = value

    if resolve_env:
        import os
        for config in config_dict.values():
            for key, value in config.items():
                if isinstance(value, str) and value.startswith('$'):
                    env_var = value[1:]
                    config[key] = os.getenv(env_var, value)

    return config_dict, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import toml
    import os

    configs = {}
    errors = []

    for config_filename in config_filenames:
        if not os.path.exists(config_filename):
            errors.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=config_filename, lineno=0, msg=f"Configuration file {config_filename} does not exist.", args=(), exc_info=None))
            continue

        try:
            with open(config_filename) as fd:
                config = toml.load(fd)
                configs[config_filename] = config
        except Exception as e:
            errors.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=config_filename, lineno=0, msg=f"Failed to parse configuration file {config_filename}: {str(e)}", args=(), exc_info=True))

    if overrides:
        for config in configs.values():
            config.update(overrides)

    if resolve_env:
        import re
        env_re = re.compile(r'\$\{([^}]+)\}')
        for config_filename, config in configs.items():
            try:
                configs[config_filename] = _resolve_env_vars(config, env_re)
            except Exception as e:
                errors.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=config_filename, lineno=0, msg=f"Failed to resolve environment variables in configuration file {config_filename}: {str(e)}", args=(), exc_info=True))

    return configs, errors

def _resolve_env_vars(d, env_re):
    if isinstance(d, dict):
        return {k: _resolve_env_vars(v, env_re) for k, v in d.items()}
    elif isinstance(d, list):
        return [_resolve_env_vars(v, env_re) for v in d]
    elif isinstance(d, str):
        return env_re.sub(lambda m: os.environ.get(m.group(1), m.group(0)), d)
    else:
        return d

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import os
    import toml  # Assuming TOML is used for configuration files

    configs = {}
    log_records = []

    for filename in config_filenames:
        if not os.path.exists(filename):
            log_record = logging.makeLogRecord({
                'levelno': logging.ERROR,
                'msg': f"Configuration file not found: {filename}"
            })
            log_records.append(log_record)
            continue

        try:
            with open(filename, 'r') as file:
                config_data = toml.load(file)
            configs[filename] = config_data
        except Exception as e:
            log_record = logging.makeLogRecord({
                'levelno': logging.ERROR,
                'msg': f"Failed to parse configuration file {filename}: {str(e)}"
            })
            log_records.append(log_record)

    if overrides:
        for key, value in overrides.items():
            for config in configs.values():
                config[key] = value

    if resolve_env:
        # Simple environment variable resolution
        import re
        env_var_pattern = re.compile(r'\${(\w+)}')

        for filename, config in configs.items():
            def resolve_env_vars(obj):
                if isinstance(obj, dict):
                    return {k: resolve_env_vars(v) for k, v in obj.items()}
                elif isinstance(obj, list):
                    return [resolve_env_vars(item) for item in obj]
                elif isinstance(obj, str):
                    match = env_var_pattern.match(obj)
                    if match:
                        env_var = match.group(1)
                        return os.environ.get(env_var, obj)
                return obj

            configs[filename] = resolve_env_vars(config)

    return configs, log_records

