def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metaclasses = {type(base) for base in bases}
    if len(metaclasses) == 1:
        return metaclasses.pop()
    common_mcs = type
    for mc in metaclasses:
        if issubclass(common_mcs, mc):
            continue
        elif issubclass(mc, common_mcs):
            common_mcs = mc
        else:
            raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")
    return common_mcs

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    elif bases:
        metaclasses = set(type(base) for base in bases)
        if len(metaclasses) == 1:
            return metaclasses.pop()
        else:
            # This is a simplified version and does not handle the full metaclass conflict resolution
            # as found in the C3 linearization algorithm. For real-world use, consider using a more
            # complete implementation.
            mro = [base.mro() if isinstance(base, type) else [base] for base in bases]
            candidates = [c.__class__ for c in mro[0] if all(c in b for b in mro[1:])]
            return candidates[0] if candidates else type
    return type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    metaclasses = set()
    for base in bases:
        metaclass = getattr(base, '__class__', None)
        if metaclass:
            metaclasses.add(metaclass)
    if explicit_mc:
        metaclasses.add(explicit_mc)
    if len(metaclasses) == 0:
        return type
    elif len(metaclasses) == 1:
        return metaclasses.pop()
    else:
        raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        metaclass = type(base)
        if isinstance(metaclass, type):
            metaclasses.add(metaclass)

    if not metaclasses:
        return type

    if len(metaclasses) == 1:
        return metaclasses.pop()

    # If multiple metaclasses, find a common base metaclass
    common_bases = []
    for metaclass in metaclasses:
        common_bases.extend(metaclass.__mro__)

    for base in common_bases:
        if all(issubclass(m, base) for m in metaclasses):
            return base

    raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of all its bases' metaclasses")

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metaclasses = set(type(base) for base in bases)
    if len(metaclasses) > 1:
        raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")
    return next(iter(metaclasses), type)

