def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    parser = self.parsers[parser_name]
    for arg, value in values_dict.items():
        if arg in parser._option_string_actions:
            action = parser._option_string_actions[arg]
            if action.type is not None:
                try:
                    values_dict[arg] = action.type(value)
                except (ValueError, TypeError) as e:
                    raise argparse.ArgumentTypeError(f"argument {arg}: {str(e)}")
        elif arg in parser._positionals._group_actions:
            action = parser._positionals._group_actions[0]
            if action.type is not None:
                try:
                    values_dict[arg] = action.type(value)
                except (ValueError, TypeError) as e:
                    raise argparse.ArgumentTypeError(f"argument {arg}: {str(e)}")

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if parser_name in self.parsers:
        parser = self.parsers[parser_name]
        for arg, value in values_dict.items():
            for action in parser._actions:
                if action.dest == arg and value != action.default:
                    try:
                        values_dict[arg] = type(action.default)(value)
                    except (ValueError, TypeError):
                        # If conversion fails, keep the original value
                        pass

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    """
    # Assuming self.parsers is a dictionary of ArgumentParser objects keyed by parser_name
    parser = self.parsers.get(parser_name)
    if not parser:
        raise ValueError(f"No parser found for {parser_name}")

    for action in parser._actions:
        if action.dest in values_dict:
            # Convert value to the appropriate type
            try:
                values_dict[action.dest] = action.type(values_dict[action.dest])
            except (ValueError, TypeError) as e:
                raise ValueError(f"Error converting {action.dest}: {str(e)}") from e

    return values_dict

